namespace docking.widgets.table.constraint;




using ghidra.util;

/**
 * String column constraint for matching column values if they match a full regular expression pattern.
 */
public class StringMatchesColumnConstraint : StringColumnConstraint {
	/**
	 * Constructor
	 *
	 * <P> This class is for users to enter true regular expression which is why it creates
	 * a pattern directly without using the {@link UserSearchUtils}.
	 *
	 * @param spec the string to use to create a "matcher" pattern.
	 */
	public StringMatchesColumnConstraint(string spec) : base(spec, "Please enter a regular expression.")
    {
	}

	/* @Override */
	public string getName() {
		return "Matches Regex";
	}

	/* @Override */
	public ColumnConstraint<string> copy(string newPatternString) {
		return new StringMatchesColumnConstraint(newPatternString);
	}

	/* @Override */
	protected Pattern generateMatchesPattern(string patternString) {
		return Pattern.compile("^" + patternString.trim() + "$");
	}

	/* @Override */
	public bool isValidPatternString(string value) {
		if (!base.isValidPatternString(value)) {
			return false;
		}
		try {
			Pattern.compile(value);
			return true;
		}
		catch (PatternSyntaxException e) {
			return false;
		}
	}

	/* @Override */
	protected Pattern generateFindsPattern() {
		return Pattern.compile("(.*)");
	}
}
